CREATE   VIEW [FO].[vwCustTrans_PennyDifferences]
AS

SELECT
	ct.[ACCOUNTINGEVENT],
	ct.[ACCOUNTNUM],
	ct.[AMOUNTCUR] AS [CustTrans_AmountCur],
	gjae.[TRANSACTIONCURRENCYAMOUNT]*-1 AS [AMOUNTCUR],
	ct.[AMOUNTMST] AS [CustTrans_AmountMst],
	gjae.[ACCOUNTINGCURRENCYAMOUNT]*-1 AS [AMOUNTMST],
	ct.[RECID] AS [CUSTTRANSRECID],
	ct.[INVOICE],
	ct.[VOUCHER],
	CASE 
		WHEN ct.DOCUMENTDATE <= '2021-08-23' AND YEAR(ct.DOCUMENTDATE) <> 1900 THEN ct.DOCUMENTDATE 
		ELSE ct.TRANSDATE 
	END AS [TRANSDATE],
	ct.[DOCUMENTDATE],
	ct.[DOCUMENTNUM],
	ct.[DUEDATE],
	ct.[CURRENCYCODE],
	ct.[DATAAREAID] AS [DATAAREAIDCUST],
	ct.[POSTINGPROFILE],
	ct.[TXT],
	ct.[LASTSETTLEDATE],
	ct.[SETTLEAMOUNTCUR],
	ct.[SETTLEAMOUNTMST],
	ct.[CLOSED],
	ct.[EXCHRATE],
	ct.[EXCHADJUSTMENT],
	ct.[PAYMMODE],
	ct.[PAYMREFERENCE],
	ct.[PAYMMETHOD],
	ct.[OFFSETRECID],
	ct.[LASTSETTLEVOUCHER],
	ct.[CREATEDDATETIME] AS [CREATEDDATETIMECUST],
	ct.[CREATEDBY] AS [CREATEDBYCUST],
	ct.[MODIFIEDDATETIME] AS [MODIFIEDDATETIMECUST],
	ct.[PARTITION],
	ct.[ORDERACCOUNT],
	ct.[TRANSTYPE],
	tt.[Description] AS [TransType_Description],
	ct.[DATAAREAID],
	ct.[DataLakeModified_DateTime] AS [SYNCSTARTDATETIME],
	ct.[RECID]
	,T2.PRODUCTCODE AS productcode
	,T2.PRODUCTGROUP AS ProductGroup --00000000
	,CASE 
		WHEN ma.MAINACCOUNTID = '000000' THEN 'VAT'
		WHEN T2.productcode IN ('RAFEE_ACAND', 'RAFEE_APCC', 'RAFEE_MRICS', 'RAFEE_PMU2', 'RAFEE_ASSOC', 'RAFEE_FRICS') THEN 'RAD'   --Readmission Fee
		WHEN T2.productgroup = 'S4' AND ma.MainAccountId = '000000' THEN 'UPG'
		WHEN T2.productgroup in ('E1','T3','T4','W1') then 'EVE'	
		--WHEN T2.PRODUCTGROUP in ('S1') AND ma.MAINACCOUNTID NOT IN ('000000', '000000') THEN 'SUB' --Definition changed to a more specific one 25/09/23 AAB
		WHEN T2.PRODUCTCODE IN ('PROAPCCAND', 'PROASSOC', 'PROASSOCCAND', 'PROFRICS', 'PROMRICS', 'PROMRICSU2') OR T2.PRODUCTCODE LIKE 'CON%' THEN 'SUB'
		WHEN T2.PRODUCTGROUP in ('F1') AND T2.[PRODUCTCODE] NOT IN ('REGDISCCOST', 'REGDISCFINE') then 'FPF'
		WHEN T2.PRODUCTCODE IN ('REGDISCCOST', 'REGDISCFINE') then 'DIS'
		WHEN T2.PRODUCTGROUP in ('B2','B3','B4') then 'BCI'
		WHEN T2.PRODUCTGROUP in ('D2','O2') then 'DRS'
		WHEN T2.PRODUCTGROUP in ('A1') then 'APP'
		WHEN T2.PRODUCTGROUP in ('J1, M2') then 'ADV'
		WHEN T2.PRODUCTGROUP in ('Q2') then 'ARC'
		WHEN T2.PRODUCTGROUP in ('P1') then 'SPO'
		WHEN T2.PRODUCTGROUP in ('R1','Q1','S3') then 'REG'
		WHEN T2.PRODUCTGROUP in ('T1') then 'K&C'
		WHEN T2.PRODUCTGROUP in ('DM') then 'DM'
		WHEN T2.PRODUCTGROUP in ('O1') then 'OLA'
		WHEN ma.MAINACCOUNTID = '000000' THEN 'LHL'
		WHEN ma.MAINACCOUNTID = '000000' THEN 'SUR'
		--WHEN ct.[INVOICE] = '00000000FTI' THEN 'LHL'
		else 'GEN' End as RICINVOICETYPE 
	,CASE 
		WHEN T2.PRODUCTCODE IN ('RAFEE_ACAND', 'RAFEE_APCC', 'RAFEE_MRICS', 'RAFEE_PMU2', 'RAFEE_ASSOC', 'RAFEE_FRICS') THEN 'RAD'   --Readmission Fee
		WHEN T2.PRODUCTGROUP = 'S4' AND ma.MAINACCOUNTID = '000000' THEN 'UPG'
		WHEN T2.PRODUCTGROUP in ('E1','T3','T4','W1') then 'EVE'	
		--WHEN T2.PRODUCTGROUP in ('S1') AND ma.MAINACCOUNTID NOT IN ('000000', '000000') THEN 'SUB' --Definition changed to a more specific one 25/09/23 AAB
		WHEN T2.PRODUCTCODE IN ('PROAPCCAND', 'PROASSOC', 'PROASSOCCAND', 'PROFRICS', 'PROMRICS', 'PROMRICSU2') OR T2.PRODUCTCODE LIKE 'CON%' THEN 'SUB'
		WHEN T2.PRODUCTGROUP in ('F1') AND T2.[PRODUCTCODE] NOT IN ('REGDISCCOST', 'REGDISCFINE') then 'FPF'
		WHEN T2.PRODUCTCODE IN ('REGDISCCOST', 'REGDISCFINE') then 'DIS'
		WHEN T2.PRODUCTGROUP in ('B2','B3','B4') then 'BCI'
		WHEN T2.PRODUCTGROUP in ('D2','O2') then 'DRS'
		WHEN T2.PRODUCTGROUP in ('A1') then 'APP'
		WHEN T2.PRODUCTGROUP in ('J1, M2') then 'ADV'
		WHEN T2.PRODUCTGROUP in ('Q2') then 'ARC'
		WHEN T2.PRODUCTGROUP in ('P1') then 'SPO'
		WHEN T2.PRODUCTGROUP in ('R1','Q1','S3') then 'REG'
		WHEN T2.PRODUCTGROUP in ('T1') then 'K&C'
		WHEN T2.PRODUCTGROUP in ('DM') then 'DM'
		WHEN T2.PRODUCTGROUP in ('O1') then 'OLA'
		WHEN ma.MAINACCOUNTID = '000000' THEN 'LHL'
		WHEN ma.MAINACCOUNTID = '000000' THEN 'SUR'
		--WHEN ct.[INVOICE] = '00000000FTI' THEN 'LHL'
		else 'GEN' END AS RICINVOICETYPE_with_Tax
	,T2.COSTCENTER AS CostCenter
	,ma.MAINACCOUNTID AS MAINACCOUNT
	,gjae.LEDGERACCOUNT AS ACCOUNTDISPLAYVALUE
	,gjae.[POSTINGTYPE]
	,pt.[Description] AS [PostingType_Description]
	,ct.[MCRPAYMORDERID] AS [ORDERNUM]
	,CAST(T2.COUNTRY AS nvarchar(5)) AS Country,
	ct.PAYMSCHEDID
-- select top 10  *-- select count(*)
FROM synapse_fo.CUSTTRANS ct --dbo.RICSBICustTransStaging ct  
	INNER JOIN synapse_fo.GENERALJOURNALENTRY gje
		ON ct.VOUCHER = gje.SUBLEDGERVOUCHER
	INNER JOIN synapse_fo.GENERALJOURNALACCOUNTENTRY gjae
		ON gje.RECID = gjae.GENERALJOURNALENTRY
	LEFT OUTER JOIN synapse_fo.DIMENSIONCOMBINATIONENTITY_RICS T2 
		ON (
				(gjae.LEDGERDIMENSION = T2.RECID) AND (gjae.PARTITION = T2.PARTITION)
			)
	LEFT JOIN synapse_fo.MAINACCOUNT ma
		ON gjae.MAINACCOUNT = ma.RECID
	LEFT JOIN [synapse_fo].[MAINACCOUNTCATEGORY] MAC
		ON MA.ACCOUNTCATEGORYREF = MAC.ACCOUNTCATEGORYREF
		AND MA.PARTITION = MAC.PARTITION
	LEFT JOIN [synapse_fo].[vwTransType] tt
		ON ct.[TRANSTYPE] = tt.[TransType]
	LEFT JOIN [synapse_fo].[vwLedgerPostingType] pt
		ON gjae.[POSTINGTYPE] = pt.[PostingType]
WHERE gjae.POSTINGTYPE = 11
	AND ct.[TRANSTYPE] = 2
